1	/**
2	 * DOM HUD overlay (never painted into the 3D world). Sizes use a 9:16 frame unit `--u`
3	 * (1u = 1% of the portrait frame height) so the layout matches the 864×1536 references.
4	 */
5	import '@fontsource/baloo-2/700.css';
6	import '@fontsource/baloo-2/800.css';
7	import type { StageId } from '../world/course';
8	import { STAGE_TITLES } from '../world/course';
9	import { on05 } from '../vfx/waterRibbon';
10	
11	/**
12	 * `?hud05=1` (or `?match05=1`), Screen 05 full reference match (qa/pilot05/full_reference_match/hud/NOTES.md): the top
13	 * bar and the level banner re-laid to the approved picture's measured pixels (864 x 1536 frame; 1 px = 1/15.36 u):
14	 * bar x 33-825 / y 13-100 (opaque flat purple ~ (88, 2, 127), light rim), heart-section capsule x 33-331, dividers at
15	 * x 344 and 707 (y 27-86), banner x 120-746 / y 113-181. The four static icons (heart, plus, coin, pause button) are
16	 * sprites cut from the approved picture (qa/pilot05/full_reference_match/hud/icon_bake.py → assets/textures/hud05/);
17	 * the hearts value, the coin counter and the level title stay live DOM text (the counter is never hard-coded).
18	 * A global HUD change: with the switch on, every ride screen shows this layout (default build unchanged).
19	 */
20	const HUD05 = on05('hud05');
21	const U = (px: number) => `calc(var(--u) * ${(px / 15.36 + 1e-5).toFixed(5)})`; // +1e-5: Chrome floors border widths
22	/** approved icon sprite boxes (frame px; assets/textures/hud05/hud05_icons.json) */
23	const ICON05 = {
24	  heart05: { url: new URL('../../assets/textures/hud05/heart05.png', import.meta.url).href, box: [60, 21, 94, 74] },
25	  plus05: { url: new URL('../../assets/textures/hud05/plus05.png', import.meta.url).href, box: [254, 28, 56, 49] },
26	  coin05: { url: new URL('../../assets/textures/hud05/coin05.png', import.meta.url).href, box: [375, 13, 90, 89] },
27	  pause05: { url: new URL('../../assets/textures/hud05/pause05.png', import.meta.url).href, box: [727, 9, 96, 96] },
28	} as const;
29	/** hud05 tuning (measured against the approved glyph boxes with qa/pilot05/full_reference_match/hud/harness.mjs) */
30	const H05 = {
31	  bar: { x0: 33, y0: 13, x1: 825, y1: 100, border: 2, shadow: true },
32	  num: { size: 53, weight: 700, track: 0.0, hX: 162, cX: 497.5, top: 26.5 },
33	  banner: { cx: 433, y0: 113, h: 68, minW: 626, size: 44, weight: 700, track: 0.0, skew: -4, italic: true, dy: 0, stroke: 0 },
34	};
35	/** absolute position inside the bar's padding box, from approved frame px */
36	const bx = (x: number) => U(x - H05.bar.x0 - H05.bar.border);
37	const by = (y: number) => U(y - H05.bar.y0 - H05.bar.border);
38	const icon05 = (k: keyof typeof ICON05, cls = 'i05') => {
39	  const { url, box: [l, t, w, h] } = ICON05[k];
40	  return `<img class="${cls}" alt="" draggable="false" src="${url}" style="left:${bx(l)};top:${by(t)};width:${U(w)};height:${U(h)}">`;
41	};
42	const CSS05 = () => `
43	#hud.m05 .bar { top: calc(${U(H05.bar.y0)} + env(safe-area-inset-top)); left: ${U(H05.bar.x0)}; right: ${U(864 - H05.bar.x1)};
44	  height: ${U(H05.bar.y1 - H05.bar.y0)}; box-sizing: border-box; border-radius: ${U((H05.bar.y1 - H05.bar.y0) / 2)}; display: block;
45	  background: linear-gradient(180deg, rgb(97,3,141) 0%, rgb(89,2,128) 16%, rgb(86,2,124) 55%, rgb(86,2,124) 88%, rgb(91,3,130) 100%);
46	  border: ${U(H05.bar.border)} solid rgb(226,150,246); border-top-color: rgb(248,178,244); border-bottom-color: rgb(196,110,228);
47	  box-shadow: inset 0 ${U(3)} ${U(1.5)} rgba(240,150,245,0.85), inset 0 ${U(8)} ${U(5)} rgba(190,30,215,0.5)${H05.bar.shadow ? `, 0 ${U(2.5)} ${U(3)} rgba(120,10,150,0.6)` : ''}; }
48	#hud.m05 .bar > * { position: absolute; display: block; margin: 0; }
49	#hud.m05 .pill05 { left: ${U(-H05.bar.border)}; top: ${U(-H05.bar.border)}; width: ${U(331 - 33)}; height: ${U(H05.bar.y1 - H05.bar.y0)};
50	  box-sizing: border-box; border-radius: ${U((H05.bar.y1 - H05.bar.y0) / 2)}; border: ${U(2)} solid rgba(214,160,255,0.8);
51	  box-shadow: inset 0 0 ${U(3)} rgba(200,140,255,0.4); }
52	#hud.m05 .div05 { top: ${by(27)}; height: ${U(59)}; width: ${U(2)}; background: rgba(226,182,255,0.33); }
53	#hud.m05 .d1 { left: ${bx(343)}; } #hud.m05 .d2 { left: ${bx(706)}; }
54	#hud.m05 .num { top: ${by(H05.num.top)}; font-weight: ${H05.num.weight}; font-size: ${U(H05.num.size)}; line-height: 1; letter-spacing: ${U(H05.num.track)};
55	  white-space: nowrap; color: #fff; text-shadow: 0 ${U(2)} ${U(1.5)} rgba(50,0,90,0.55); }
56	#hud.m05 .n05h { left: ${bx(H05.num.hX)}; } #hud.m05 .n05c { left: ${bx(H05.num.cX)}; }
57	#hud.m05 .p05 { left: ${bx(ICON05.pause05.box[0])}; top: ${by(ICON05.pause05.box[1])}; width: ${U(ICON05.pause05.box[2])}; height: ${U(ICON05.pause05.box[3])};
58	  border: 0; border-radius: 50%; background: none; gap: 0; padding: 0; }
59	#hud.m05 .p05 img { position: absolute; inset: 0; width: 100%; height: 100%; }
60	#hud.m05 .banner { left: ${U(H05.banner.cx)}; top: calc(${U(H05.banner.y0)} + env(safe-area-inset-top)); height: ${U(H05.banner.h)};
61	  min-width: ${U(H05.banner.minW)}; box-sizing: border-box; padding: 0 ${U(12)}; justify-content: center; border-radius: ${U(H05.banner.h / 2)};
62	  background: linear-gradient(180deg, rgb(99,3,147) 0%, rgb(96,3,144) 50%, rgb(94,3,140) 100%);
63	  border: ${U(2.5)} solid rgb(246,168,72); border-top-color: rgb(255,230,205); border-bottom-color: rgb(252,222,170);
64	  box-shadow: inset 0 0 0 ${U(1)} rgba(205,112,86,0.85), inset 0 ${U(-6)} ${U(5)} rgba(175,25,195,0.6); }
65	#hud.m05 .banner span { font-size: ${U(H05.banner.size)}; font-weight: ${H05.banner.weight}; position: relative; top: ${U(H05.banner.dy)}; letter-spacing: ${U(H05.banner.track)}; font-style: ${H05.banner.italic ? 'italic' : 'normal'};
66	  transform: skewX(${H05.banner.skew}deg); line-height: 1;
67	  background: linear-gradient(180deg, #fadcb2 0%, #f8d8aa 50%, #f6d2a2 100%); -webkit-background-clip: text; background-clip: text; color: transparent;
68	  ${H05.banner.stroke ? `-webkit-text-stroke: ${U(H05.banner.stroke)} rgba(105,25,85,0.9);` : ''} filter: drop-shadow(0 ${U(1.2)} 0 rgba(90,10,70,0.85)); }
69	`;
