71	const CSS = `
72	:root { --u: min(1vh, calc(100vw / 56.25)); }
73	#hud { position: fixed; inset: 0; pointer-events: none; font-family: 'Baloo 2', system-ui, sans-serif; z-index: 10;
74	  display: flex; justify-content: center; }
75	#hud .frame { position: relative; width: calc(var(--u) * 56.25); height: 100%; }
76	#hud .bar { position: absolute; top: calc(var(--u) * 1.15 + env(safe-area-inset-top)); left: calc(var(--u) * 2.3); right: calc(var(--u) * 2.3);
77	  height: calc(var(--u) * 5.5); border-radius: calc(var(--u) * 2.8);
78	  background: linear-gradient(180deg, rgba(150,60,200,0.72), rgba(92,22,150,0.78));
79	  border: calc(var(--u) * 0.22) solid rgba(255,220,255,0.55);
80	  box-shadow: inset 0 calc(var(--u)*0.35) calc(var(--u)*0.6) rgba(255,255,255,0.35), 0 calc(var(--u)*0.3) calc(var(--u)*1.2) rgba(60,0,90,0.45);
81	  display: flex; align-items: center; color: #fff; pointer-events: auto; }
82	#hud .seg { display: flex; align-items: center; height: 100%; }
83	#hud .hearts { width: 37%; padding-left: calc(var(--u) * 2.2); gap: calc(var(--u) * 1.2); }
84	#hud .coins { flex: 1; justify-content: center; gap: calc(var(--u) * 2.4); border-left: calc(var(--u)*0.12) solid rgba(255,255,255,0.25); border-right: calc(var(--u)*0.12) solid rgba(255,255,255,0.25); }
85	#hud .pause { width: 14%; justify-content: center; }
86	#hud .num { font-weight: 700; font-size: calc(var(--u) * 2.75); letter-spacing: calc(var(--u)*0.05); text-shadow: 0 calc(var(--u)*0.15) 0 rgba(60,0,100,0.5); }
87	#hud .plus { font-weight: 800; font-size: calc(var(--u) * 3.4); line-height: 1; margin-left: calc(var(--u)*0.6); }
88	#hud .icon { width: calc(var(--u) * 4.0); height: calc(var(--u) * 4.0); display: block; }
89	#hud .pbtn { width: calc(var(--u) * 4.6); height: calc(var(--u) * 4.6); border-radius: 50%; border: calc(var(--u)*0.3) solid rgba(255,255,255,0.9);
90	  background: radial-gradient(circle at 40% 30%, rgba(190,110,240,0.9), rgba(100,30,160,0.95)); display: flex; align-items: center; justify-content: center; gap: calc(var(--u)*0.6); cursor: pointer; }
91	#hud .pbtn i { display: block; width: calc(var(--u)*0.75); height: calc(var(--u)*2.0); border-radius: calc(var(--u)*0.4); background: #fff; }
92	#hud .banner { position: absolute; top: calc(var(--u) * 7.55 + env(safe-area-inset-top)); left: 50%; transform: translateX(-50%);
93	  height: calc(var(--u) * 4.1); padding: 0 calc(var(--u) * 3.0); border-radius: calc(var(--u) * 2.1); white-space: nowrap;
94	  background: linear-gradient(180deg, #7a2bb0, #4f1489); border: calc(var(--u)*0.22) solid #ffd36b;
95	  box-shadow: inset 0 calc(var(--u)*0.3) calc(var(--u)*0.5) rgba(255,255,255,0.25), 0 0 calc(var(--u)*1.2) rgba(255,190,90,0.45);
96	  display: flex; align-items: center; }
97	#hud .banner span { font-weight: 800; font-style: italic; font-size: calc(var(--u) * 2.45); letter-spacing: calc(var(--u)*0.06);
98	  background: linear-gradient(180deg, #fffbe8 0%, #ffe9a8 55%, #ffd36b 100%); -webkit-background-clip: text; background-clip: text; color: transparent;
99	  filter: drop-shadow(0 calc(var(--u)*0.12) 0 rgba(80,0,90,0.6)); display: inline-block; transform: skewX(-8deg); }
100	#hud .hidden { display: none !important; }
101	#hud .victory { position: absolute; left: 50%; bottom: calc(var(--u) * 3.4); transform: translateX(-50%); width: calc(var(--u) * 49); height: calc(var(--u) * 13.5); }
102	#hud .victory .pill { position: absolute; left: calc(var(--u)*8.5); right: calc(var(--u)*8.5); top: calc(var(--u) * 3.1); bottom: calc(var(--u)*0.6);
103	  border-radius: calc(var(--u) * 5); background: linear-gradient(180deg, #8b34c4, #4d128a); border: calc(var(--u)*0.45) solid #ffcd5a;
104	  box-shadow: 0 0 calc(var(--u)*2) rgba(255,200,90,0.7), inset 0 calc(var(--u)*0.5) calc(var(--u)*0.6) rgba(255,255,255,0.3);
105	  display: flex; align-items: center; justify-content: center; text-align: center; }
106	#hud .victory .pill span { font-weight: 800; font-size: calc(var(--u) * 3.35); line-height: 1.02; color: #ffe9a6; letter-spacing: calc(var(--u)*0.05);
107	  background: linear-gradient(180deg, #fffaf0, #ffe08a 60%, #ffc548); -webkit-background-clip: text; background-clip: text; color: transparent;
108	  filter: drop-shadow(0 calc(var(--u)*0.18) 0 rgba(70,0,80,0.7)); }
109	#hud .victory .medal { position: absolute; left: 50%; top: 0; transform: translateX(-50%); width: calc(var(--u)*6.2); height: calc(var(--u)*6.2); }
110	#hud .victory .laurel { position: absolute; top: calc(var(--u)*3.6); width: calc(var(--u)*9.5); height: calc(var(--u)*9.8); }
111	#hud .victory .laurel.l { left: calc(var(--u)*1.0); }
112	#hud .victory .laurel.r { right: calc(var(--u)*1.0); transform: scaleX(-1); }
113	#hud .victory.pop { animation: rbPop 0.7s cubic-bezier(.2,1.6,.4,1) both; }
114	@keyframes rbPop { from { transform: translateX(-50%) scale(0.2); opacity: 0; } to { transform: translateX(-50%) scale(1); opacity: 1; } }
115	#hud .replay { position: absolute; left: 50%; bottom: calc(var(--u) * 18.5); transform: translateX(-50%); pointer-events: auto; cursor: pointer;
116	  font-weight: 800; font-size: calc(var(--u)*2.2); color: #fff; padding: calc(var(--u)*0.6) calc(var(--u)*2.4); border-radius: calc(var(--u)*2);
117	  background: rgba(110,30,170,0.75); border: calc(var(--u)*0.2) solid #ffd36b; }
118	#hud .pausedOverlay { position: absolute; inset: 0; background: rgba(40,0,70,0.45); display: flex; align-items: center; justify-content: center; pointer-events: auto; }
119	#hud .pausedOverlay div { font-weight: 800; font-size: calc(var(--u)*4); color: #fff; text-shadow: 0 0 calc(var(--u)*1) #b04ad8; }
120	#hud .hint { position: absolute; bottom: calc(var(--u)*4); left: 50%; transform: translateX(-50%); color: rgba(255,255,255,0.85); font-weight: 700; font-size: calc(var(--u)*1.8);
121	  text-shadow: 0 0 calc(var(--u)*0.6) rgba(120,0,160,0.9); }
122	#hud .flash { position: absolute; inset: 0; background: rgba(255,80,140,0.0); transition: background 0.25s; }
123	`;
