135	export interface Hud {
136	  setVisible(v: boolean): void;
137	  setStage(id: StageId): void;
138	  setCoins(n: number): void;
139	  setHearts(n: number, max?: number): void;
140	  showVictory(v: boolean, animate?: boolean): void;
141	  showPaused(v: boolean): void;
142	  showHint(text: string | null): void;
143	  flashHurt(): void;
144	  onPause(cb: () => void): void;
145	  onReplay(cb: () => void): void;
146	  root: HTMLElement;
147	}
148	
149	export function createHud(): Hud {
150	  const style = document.createElement('style');
151	  style.textContent = HUD05 ? CSS + CSS05() : CSS;
152	  document.head.appendChild(style);
153	  const root = document.createElement('div');
154	  root.id = 'hud';
155	  if (HUD05) root.classList.add('m05');
156	  const bar05 = `<div class="bar">
157	      <i class="pill05"></i>${icon05('heart05')}<span class="num n05h" data-k="hearts">5/5</span>${icon05('plus05')}
158	      <i class="div05 d1"></i>${icon05('coin05')}<span class="num n05c" data-k="coins">1,330</span><i class="div05 d2"></i>
159	      <div class="pbtn p05" data-k="pause"><img alt="" draggable="false" src="${ICON05.pause05.url}"></div>
160	    </div>`;
161	  root.innerHTML = `<div class="frame">
162	    <div class="flash"></div>
163	    ${HUD05 ? bar05 : `<div class="bar">
164	      <div class="seg hearts">${HEART}<span class="num" data-k="hearts">5/5</span><span class="plus">+</span></div>
165	      <div class="seg coins">${COIN}<span class="num" data-k="coins">1,330</span></div>
166	      <div class="seg pause"><div class="pbtn" data-k="pause"><i></i><i></i></div></div>
167	    </div>`}
168	    <div class="banner"><span data-k="title">03 · WHIRLPOOL TWIRL</span></div>
169	    <div class="victory hidden"><div class="laurel l">${LAUREL}</div><div class="laurel r">${LAUREL}</div><div class="pill"><span>FINAL SPIN<br>COMPLETE</span></div><div class="medal">${MEDAL}</div></div>
170	    <div class="replay hidden" data-k="replay">↻ Replay</div>
171	    <div class="hint hidden"></div>
172	    <div class="pausedOverlay hidden"><div>PAUSED</div></div>
173	  </div>`;
174	  document.body.appendChild(root);
175	  const $ = (k: string) => root.querySelector(`[data-k="${k}"]`) as HTMLElement;
176	  const bar = root.querySelector('.bar') as HTMLElement;
177	  const banner = root.querySelector('.banner') as HTMLElement;
178	  const victory = root.querySelector('.victory') as HTMLElement;
179	  const paused = root.querySelector('.pausedOverlay') as HTMLElement;
180	  const hint = root.querySelector('.hint') as HTMLElement;
181	  const flash = root.querySelector('.flash') as HTMLElement;
182	  let pauseCb = () => {};
183	  let replayCb = () => {};
184	  $('pause').addEventListener('pointerdown', (e) => { e.stopPropagation(); pauseCb(); });
185	  paused.addEventListener('pointerdown', (e) => { e.stopPropagation(); pauseCb(); });
186	  $('replay').addEventListener('pointerdown', (e) => { e.stopPropagation(); replayCb(); });
187	  return {
188	    root,
189	    setVisible(v) { bar.classList.toggle('hidden', !v); banner.classList.toggle('hidden', !v); },
190	    setStage(id) { $('title').textContent = `${id} · ${STAGE_TITLES[id]}`; },
191	    setCoins(n) { $('coins').textContent = n.toLocaleString('en-US'); },
192	    setHearts(n, max = 5) { $('hearts').textContent = `${n}/${max}`; },
193	    showVictory(v, animate = true) {
194	      victory.classList.toggle('hidden', !v);
195	      victory.classList.toggle('pop', v && animate);
196	      $('replay').classList.add('hidden');
197	      if (v) setTimeout(() => { if (!victory.classList.contains('hidden')) $('replay').classList.remove('hidden'); }, 2600);
198	    },
199	    showPaused(v) { paused.classList.toggle('hidden', !v); },
200	    showHint(t) { hint.classList.toggle('hidden', !t); hint.textContent = t ?? ''; },
201	    flashHurt() { flash.style.background = 'rgba(255,80,140,0.35)'; setTimeout(() => (flash.style.background = 'rgba(255,80,140,0)'), 180); },
202	    onPause(cb) { pauseCb = cb; },
203	    onReplay(cb) { replayCb = cb; },
204	  };
205	}
