113	function coins05(course: Course, add: (stage: StageId, s: number, lat: number, h?: number, extra?: Partial<CoinDef>) => void) {
114	  const a = course.stage('05');
115	  const sCp = course.marks['05_crest'];
116	  const extra = { scale: C05.scale, tilt: C05.tilt };
117	  const ss: number[] = [];
118	  // gameplay trail before the checkpoint ends 1 u behind Benny's checkpoint spot (never between him and the camera view)
119	  for (let s = sCp - 1; s > a.s0 + 6; s -= C05.preGap) ss.unshift(s);
120	  for (let k = 0, s = sCp + C05.first; s < a.s1 - 3; k++) { ss.push(s); s += Math.min(C05.gapMax, C05.gap0 + k * C05.gapGrow); }
121	  // latK < 1: the trail winds with the cyan core but stays inside its middle (the core half width is
122	  // ≥ 2 u), so the far coins converge on the VP like the ref instead of swinging out to the pink bands
123	  for (const s of ss) add('05', s, C05.latK * coreLateral(course, s), C05.h, extra);
124	}
