126	export function coinLayout(course: Course): CoinDef[] {
127	  const out: CoinDef[] = [];
128	  const add = (stage: StageId, s: number, lat: number, h = 0.9, extra: Partial<CoinDef> = {}) => out.push({ s, lat, h, stage, ...extra });
129	  const st = (id: StageId) => course.stage(id);
130	  // 03 — spiral trail ahead of Benny toward the drain
131	  { const a = st('03'); for (let i = 0; i < 9; i++) add('03', a.s0 + 6 + i * 2.7, 0.9 - i * 0.12); }
132	  // 04 — along the left edge of the slide
133	  { const a = st('04'); for (let i = 0; i < 8; i++) add('04', a.s0 + 9 + i * 3.6, -1.35); }
134	  // 05 — on the winding cyan core (see C05)
135	  coins05(course, add);
136	  // 06 — up and over the crest (left of centre like the ref)
137	  { const a = st('06'); const n = 18; for (let i = 0; i < n; i++) { const s = a.s0 + 4 + i * ((a.s1 - a.s0 - 6) / n); add('06', s, -1.3 + 0.7 * Math.sin(i * 0.4)); } }
138	  // 07 — winding trail, continuing down the plunge
139	  { const a = st('07'); const n = 24; for (let i = 0; i < n; i++) { const s = a.s0 + 6 + i * ((a.s1 - a.s0 - 10) / n); add('07', s, 1.0 * Math.sin(i * 0.5 + 1)); } }
140	  // 08 — S toward the platform
141	  { const a = st('08'); for (let i = 0; i < 8; i++) add('08', a.s0 + 3 + i * 1.9, -0.6 + 0.9 * Math.sin(i * 0.8)); }
142	  // 09 — arc along the left (inside of the bend, under the wave)
143	  { const a = st('09'); for (let i = 0; i < 9; i++) add('09', a.s0 + 1.5 + i * 1.7, -1.7 + i * 0.12); }
144	  // 10 — straight line into the towel tunnel
145	  { const a = st('10'); for (let i = 0; i < 5; i++) add('10', a.s0 + 1.5 + i * 2.0, -0.15); }
146	  if (!COINS05) return out;
147	  // coins05: keep every coin's bob phase, swap the 05 coins after the checkpoint for the measured arrangement (C05M)
148	  out.forEach((d, i) => { d.phase = i; });
149	  const sCp = course.marks['05_crest'];
150	  const first = out.findIndex((d) => d.stage === '05' && d.s > sCp);
151	  const kept = out.filter((d) => !(d.stage === '05' && d.s > sCp));
152	  const a5 = st('05');
153	  const meas: CoinDef[] = C05M.map(([ds, lat, scale], k) => ({
154	    s: sCp + ds, lat, h: C05.h, stage: sCp + ds < a5.s1 ? '05' : '06', scale: C05M_NEAR(k), tilt: C05.tilt, phase: first + k,
155	    far: [scale, ds],
156	  }));
157	  kept.splice(first, 0, ...meas);
158	  return kept;
159	}
