161	export interface CoinSystem {
162	  group: THREE.Group;
163	  defs: CoinDef[];
164	  collected: Uint8Array;
165	  /** returns number of coins picked up this frame */
166	  update(time: number, dt: number, bennyS: number, bennyLat: number): number;
167	  /** mark coins before s as collected (deterministic QA checkpoint state) or reset all */
168	  resetUntil(s: number): void;
