171	export function createCoins(course: Course): CoinSystem {
172	  const defs = coinLayout(course);
173	  const faceTex = canvasTexture(256, 256, (c, w, h) => {
174	    const g = c.createRadialGradient(w * 0.38, h * 0.32, 10, w / 2, h / 2, w * 0.55);
175	    g.addColorStop(0, '#ffe680');
176	    g.addColorStop(0.45, '#ffcf2a');
177	    g.addColorStop(1, '#e89200');
178	    c.fillStyle = g;
179	    c.beginPath(); c.arc(w / 2, h / 2, w / 2, 0, Math.PI * 2); c.fill();
180	    // raised inner rim: dark groove + bright lip
181	    c.lineWidth = 9;
182	    c.strokeStyle = '#c98200'; c.beginPath(); c.arc(w / 2 + 2, h / 2 + 2, w * 0.4, 0, Math.PI * 2); c.stroke();
183	    c.strokeStyle = '#fff0a0'; c.beginPath(); c.arc(w / 2 - 1, h / 2 - 1, w * 0.4, 0, Math.PI * 2); c.stroke();
184	    // embossed "$" drawn as vector strokes (font-independent: identical on every Android device):
185	    // light bevel up-left, dark bevel down-right, deep-gold glyph on top
186	    const dollar = (dx: number, dy: number, col: string, lw: number) => {
187	      c.save(); c.translate(dx, dy);
188	      c.strokeStyle = col; c.lineCap = 'round'; c.lineJoin = 'round';
189	      c.lineWidth = lw;
190	      c.beginPath();
191	      c.moveTo(166, 90);
192	      c.bezierCurveTo(150, 66, 90, 64, 90, 98);
193	      c.bezierCurveTo(90, 128, 166, 124, 166, 160);
194	      c.bezierCurveTo(166, 196, 104, 198, 88, 168);
195	      c.stroke();
196	      c.lineWidth = lw * 0.62;
197	      c.beginPath(); c.moveTo(128, 50); c.lineTo(128, 206); c.stroke();
198	      c.restore();
199	    };
200	    dollar(3, 4, '#7a3c00', 32); // drop shadow
201	    dollar(0, 0, '#b86400', 30); // dark outline
202	    dollar(0, 0, '#ffe55a', 18); // bright raised glyph
203	    dollar(-3, -3, '#fff8d0', 6); // top-left bevel highlight
204	  });
205	  // the cylinder cap's UVs run sideways once the coin is stood up (rotateX): turn the face art upright
206	  faceTex.center.set(0.5, 0.5);
207	  faceTex.rotation = -Math.PI / 2;
208	  // milled (ridged) gold edge, as on the ref coins
209	  const edgeTex = canvasTexture(256, 8, (c, w, h) => {
210	    for (let x = 0; x < w; x += 4) { c.fillStyle = (x / 4) % 2 ? '#c08000' : '#ffe070'; c.fillRect(x, 0, 4, h); }
211	  });
212	  const geo = new THREE.CylinderGeometry(0.5, 0.5, COINS05 ? C05LOOK.thick : 0.2, 48, 1);
213	  geo.rotateX(Math.PI / 2); // faces along ±Z
214	  // Gold is carried mostly by EMISSIVE art (blue ≈ 0) so the pink-white candy environment and the
215	  // Neutral tone mapping cannot wash it to pale peach (ref face ≈ #F4C400); a dark-gold metal base
216	  // keeps a reflective sheen on top.
217	  const side = new THREE.MeshStandardMaterial({ color: '#6a4a00', metalness: 0.75, roughness: 0.3, emissive: '#ffffff', emissiveMap: edgeTex, emissiveIntensity: 1.0 });
218	  const face = new THREE.MeshStandardMaterial({ map: faceTex, color: '#7a5200', metalness: 0.7, roughness: 0.3, emissive: '#ffffff', emissiveMap: faceTex, emissiveIntensity: 1.15 });
219	  let mats: THREE.Material[] = [side, face, face];
220	  if (COINS05 && face05) {
221	    const f05 = face05 as THREE.Texture;
222	    f05.center.set(0.5, 0.5);
223	    f05.rotation = faceTex.rotation; // same cap orientation as the default art
224	    const face5 = coin05Material(f05);
225	    mats = [coin05Material(edge05Texture()), face5, face5];
226	  }
227	  const mesh = new THREE.InstancedMesh(geo, mats, defs.length);
228	  mesh.frustumCulled = false;
229	  const group = new THREE.Group();
230	  group.name = 'coins';
231	  group.add(mesh);
232	  const collected = new Uint8Array(defs.length);
233	  const popT = new Float32Array(defs.length).fill(-1);
234	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), basis = new THREE.Matrix4();
235	  const p = new THREE.Vector3(), sc = new THREE.Vector3();
236	  const spin = new THREE.Quaternion(), axis = new THREE.Vector3();
237	  const tiltQ = new THREE.Quaternion(), xAxis = new THREE.Vector3(1, 0, 0);
238	  const back = new THREE.Vector3();
239	
240	  let lastS = -1e9; // Benny's s at the last update (coins05 far-scale)
241	  const place = (time: number) => {
242	    defs.forEach((d, i) => {
243	      const f = course.sample(d.s);
244	      const ph = d.phase ?? i;
245	      let scale = 1;
246	      if (collected[i]) {
247	        if (popT[i] < 0) { sc.setScalar(0); m.compose(p.set(0, -9999, 0), q.identity(), sc); mesh.setMatrixAt(i, m); return; }
248	        const k = THREE.MathUtils.clamp((time - popT[i]) / 0.35, 0, 1);
249	        if (k >= 1) { popT[i] = -1; sc.setScalar(0); m.compose(p.set(0, -9999, 0), q.identity(), sc); mesh.setMatrixAt(i, m); return; }
250	        scale = 1 + k * 0.8;
251	        p.copy(f.pos).addScaledVector(f.right, d.lat).addScaledVector(f.up, d.h + k * 1.6);
252	      } else {
253	        p.copy(f.pos).addScaledVector(f.right, d.lat).addScaledVector(f.up, d.h + 0.08 * Math.sin(time * 3 + ph));
254	      }
255	      back.copy(f.tan).negate();
256	      const right = new THREE.Vector3().crossVectors(f.up, back).normalize();
257	      basis.makeBasis(right, f.up, back);
258	      q.setFromRotationMatrix(basis);
259	      // tilted coins (05) only wobble a little so the face stays toward the camera
260	      spin.setFromAxisAngle(axis.set(0, 1, 0), (d.tilt ? 0.18 : 0.35) * Math.sin(time * 2.2 + ph * 0.7));
261	      q.multiply(spin);
262	      if (d.tilt) q.multiply(tiltQ.setFromAxisAngle(xAxis, -d.tilt));
263	      let base = d.scale ?? 1;
264	      if (d.far) {
265	        // coins05: the measured checkpoint size while at least (checkpoint distance − 1) ahead, full size 15 u closer
266	        const k = THREE.MathUtils.clamp((d.far[1] - 1 - (d.s - lastS)) / 15, 0, 1);
267	        base = d.far[0] + (base - d.far[0]) * k;
268	      }
269	      m.compose(p, q, sc.setScalar(base * scale * (collected[i] ? 1 - (time - popT[i]) / 0.35 : 1)));
270	      mesh.setMatrixAt(i, m);
271	    });
272	    mesh.instanceMatrix.needsUpdate = true;
273	  };
274	  place(0);
275	
276	  return {
277	    group,
278	    defs,
279	    collected,
280	    update(time, _dt, s, lat) {
281	      lastS = s;
282	      let picked = 0;
283	      for (let i = 0; i < defs.length; i++) {
284	        if (collected[i]) continue;
285	        const d = defs[i];
286	        const ds = d.s - s;
287	        if (ds < -2 || ds > 2) continue;
288	        if (Math.abs(ds) < 1.0 && Math.abs(d.lat - lat) < 1.25) {
289	          collected[i] = 1;
290	          popT[i] = time;
291	          picked++;
292	        }
293	      }
294	      place(time);
295	      return picked;
296	    },
297	    resetUntil(s) {
298	      lastS = s - 0.5;
299	      for (let i = 0; i < defs.length; i++) { collected[i] = defs[i].s < s ? 1 : 0; popT[i] = -1; }
300	      place(0);
301	    },
302	  };
303	}
